  ('9db2727d-8fc3-423e-a22e-1cff85059aab', 'c0734545-a8ae-47ef-bdd6-0b3f2c8af3f1', $$keuze tussen lineaire en annuïtaire aflossing$$,
   $$bedrijfseconomie-havo-2022-iii-micran-context3.png$$,
   $$Micran had bij het afsluiten van de hypothecaire lening de keuze uit een hypothecaire lening met lineaire aflossing en een hypothecaire lening met aflossing op basis van annuïteiten.$$, 'inline'),
  ('cb71a11c-a506-4859-a45c-eca8b84f7353', 'c0734545-a8ae-47ef-bdd6-0b3f2c8af3f1', $$verduurzamen van de woning: verhogen hypothecaire lening$$,
   $$bedrijfseconomie-havo-2022-iii-micran-context4.png$$,
   $$Met het oog op de klimaatdoelstellingen worden woningen steeds vaker verduurzaamd. Micran wil zijn huis ook verduurzamen. Voor de financiering van de investering in isolatie en warmtepomp denkt hij een bedrag van € 15.000 nodig te hebben. Daarvoor wil hij zijn hypothecaire lening verhogen. De bank is alleen onder bepaalde voorwaarden hiertoe bereid.$$, 'inline'),
  ('f465dddd-1274-490b-9a27-64aaa7688a7c', '31e238ee-0260-4396-99c6-1ad397837616', $$tante Beth wil € 5.000 schenken$$,
   $$bedrijfseconomie-havo-2022-iii-tante-beth-context1.png$$,
   $$Tante Beth wil € 5.000 schenken aan of haar nichtje Phillippa of aan het Wereld Natuur Fonds (WNF). Beth heeft zich verdiept in de wetgeving rond schenken.$$, 'inline'),
